(()=>{'use strict';const timer=document.getElementById('countdown');function tick(){const now=new Date();let target=new Date(now.getFullYear()+'-12-25T00:00:00-03:00');if(now>=target)target=new Date((now.getFullYear()+1)+'-12-25T00:00:00-03:00');const seconds=Math.max(0,Math.floor((target-now)/1000));const days=Math.floor(seconds/86400);const hours=Math.floor(seconds%86400/3600);const minutes=Math.floor(seconds%3600/60);const secs=seconds%60;timer.textContent=days+'d '+String(hours).padStart(2,'0')+'h '+String(minutes).padStart(2,'0')+'m '+String(secs).padStart(2,'0')+'s'}tick();setInterval(tick,1000);const sticky=document.querySelector('.sticky'),hero=document.querySelector('.hero'),offer=document.getElementById('oferta');let heroVisible=true,offerVisible=false;if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.target===hero)heroVisible=e.isIntersecting;else offerVisible=e.isIntersecting});sticky.classList.toggle('is-visible',!heroVisible&&!offerVisible)});observer.observe(hero);observer.observe(offer)}})();
(()=>{'use strict';const track=document.querySelector('.reviews'),pause=document.querySelector('[data-review-pause]'),previous=document.querySelector('[data-review-prev]'),next=document.querySelector('[data-review-next]');if(!track||!pause)return;const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduce,hover=false,focused=false,visible=false;const sync=()=>{pause.textContent=paused?'Reproduzir avaliações':'Pausar avaliações';pause.setAttribute('aria-pressed',String(paused))};function move(direction){const card=track.querySelector('.review');if(!card)return;const step=card.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap||0);const max=track.scrollWidth-track.clientWidth;let target=track.scrollLeft+direction*step;if(target>max+3)target=0;if(target< -3)target=max;track.scrollTo({left:Math.min(max,Math.max(0,target)),behavior:reduce?'instant':'smooth'})}pause.addEventListener('click',()=>{paused=!paused;sync()});previous.addEventListener('click',()=>{paused=true;sync();move(-1)});next.addEventListener('click',()=>{paused=true;sync();move(1)});track.addEventListener('mouseenter',()=>hover=true);track.addEventListener('mouseleave',()=>hover=false);track.addEventListener('focusin',()=>focused=true);track.addEventListener('focusout',()=>focused=false);track.addEventListener('pointerdown',()=>{paused=true;sync()});track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();paused=true;sync();move(e.key==='ArrowRight'?1:-1)}});if('IntersectionObserver'in window){new IntersectionObserver(entries=>{visible=entries[0].isIntersecting},{threshold:.2}).observe(track)}else visible=true;setInterval(()=>{if(!paused&&!hover&&!focused&&visible&&!document.hidden)move(1)},4500);sync()})();
